"""Run from the app folder: python patch_answer_repair.py  (backs up files; all-or-nothing; idempotent)
Needs agent/confidence.py (already installed). Adds: one corrective pass when an answer states figures no tool returned,
and SET DATEFORMAT ymd on every LIS connection (ISO dates read correctly on dmy/British logins)."""
import os, shutil, sys, time
EDITS = {
 "agent/agent.py": [('def _run_tool_loop(llm_with_tools, messages, tools_by_name: dict, tool_extra_kwargs: dict = None):\n', 'def _q_text(messages):\n    """The user\'s question = the last human message that is not our own instruction."""\n    for m in reversed(messages):\n        if isinstance(m, HumanMessage):\n            c = str(getattr(m, "content", "") or "")\n            if not c.startswith(("Give your best final answer", "Check your answer")):\n                return c\n    return ""\n\n\ndef _repair_answer(text, ok_results, messages, llm_with_tools, question=""):\n    """One corrective pass when the answer states figures that no tool returned (agent/answer_repair.py)."""\n    if not text or not ok_results:\n        return text\n    try:\n        from agent.answer_repair import maybe_repair\n        from langchain_core.messages import AIMessage\n        plain = getattr(llm_with_tools, "bound", llm_with_tools)\n\n        def ask(prompt):\n            msgs = list(messages) + [AIMessage(content=text), HumanMessage(content=prompt)]\n            r = _invoke_with_retry(plain, msgs, retries=0, fallback_tools=None)\n            return _extract_text(r.content) if r is not None else None\n\n        out, did = maybe_repair(text, ok_results, question, ask)\n        if did:\n            print("[repair] ungrounded figures corrected", flush=True)\n        return out\n    except Exception as e:\n        print(f"[repair] skipped: {e}", flush=True)\n        return text\n\n\ndef _run_tool_loop(llm_with_tools, messages, tools_by_name: dict, tool_extra_kwargs: dict = None):\n'),
  ('        if not getattr(response, "tool_calls", None):\n            return _integrity_guard(_extract_text(response.content) or None, ok_results, bad_results, tools_used, bool(verified)), total_tokens\n        if time.time()', '        if not getattr(response, "tool_calls", None):\n            _txt = _repair_answer(_extract_text(response.content) or None, ok_results, messages, llm_with_tools, _q_text(messages))\n            return _integrity_guard(_txt, ok_results, bad_results, tools_used, bool(verified)), total_tokens\n        if time.time()'),
  ('                + last_tool_text[:800] + "\\n\\nTry rephrasing with one branch or one month.")\n    return _integrity_guard(text or None,', '                + last_tool_text[:800] + "\\n\\nTry rephrasing with one branch or one month.")\n    text = _repair_answer(text or None, ok_results, messages, llm_with_tools, _q_text(messages))\n    return _integrity_guard(text or None,')],
 "database/connection.py": [('            conn.timeout = settings.query_timeout_seconds\n            return conn\n', '            conn.timeout = settings.query_timeout_seconds\n            # Language-neutral dates: \'YYYY-MM-DD\' strings are read as year-month-day on EVERY client,\n            # even if the login\'s default language is dmy/British (otherwise 2026-03-04 can mean 3 April).\n            try:\n                _c = conn.cursor()\n                _c.execute("SET DATEFORMAT ymd")\n                _c.close()\n            except Exception as _e:\n                print(f"[get_hospital_connection] SET DATEFORMAT skipped: {_e}")\n            return conn\n')],
}
NEWFILE = ("agent/answer_repair.py", '"""Self-check for AI answers: figures not found in the database results get ONE corrective pass.\n\nPure helpers + one function that takes the model call as a callable, so it is testable offline.\nNever raises; on any problem the original answer is returned unchanged."""\nfrom __future__ import annotations\n\nfrom agent import confidence as _c\n\nMAX_FIGURES_SHOWN = 6\n\n\ndef find_ungrounded(answer, ok_results, question=""):\n    """Figures in the answer that appear in no tool result (and not in the question itself)."""\n    if not answer or not ok_results:\n        return [], 0\n    pool = []\n    for r in ok_results:\n        pool += _c._numbers(str(r))\n    qn = set(_c._numbers(question))\n    claims = [v for v in _c._numbers(answer) if v not in qn]\n    return [v for v in claims if not _c._grounded(v, pool)], len(claims)\n\n\ndef needs_repair(missing, total_claims):\n    """Repair only when it is clearly worth an extra model call: >=2 unsupported figures, or most of them."""\n    if not missing:\n        return False\n    return len(missing) >= 2 or (total_claims and len(missing) / total_claims >= 0.5)\n\n\ndef _fmt(v):\n    return f"{v:,.0f}" if float(v).is_integer() else f"{v:,.2f}"\n\n\ndef repair_prompt(missing):\n    shown = ", ".join(_fmt(v) for v in missing[:MAX_FIGURES_SHOWN])\n    return ("Check your answer against the tool results above. These figures do not appear in any tool result: "\n            f"{shown}. For each one: if you calculated it, keep it and state the calculation in a few words using "\n            "figures from the results; otherwise remove it or say the value could not be verified. "\n            "Do not add any new figures. Reply with the corrected answer only, in the same format and language.")\n\n\ndef maybe_repair(answer, ok_results, question, ask_model):\n    """ask_model(prompt:str) -> str|None. Returns (answer, repaired:bool)."""\n    try:\n        missing, total = find_ungrounded(answer, ok_results, question)\n        if not needs_repair(missing, total):\n            return answer, False\n        fixed = ask_model(repair_prompt(missing))\n        if not fixed or not str(fixed).strip():\n            return answer, False\n        fixed = str(fixed).strip()\n        left, _ = find_ungrounded(fixed, ok_results, question)\n        # accept only if it did not get worse and is not a degenerate reply\n        if len(left) < len(missing) and len(fixed) >= 0.3 * len(answer):\n            return fixed, True\n        return answer, False\n    except Exception:\n        return answer, False\n')
if os.path.exists(NEWFILE[0]) and "def _repair_answer(" in open("agent/agent.py", encoding="utf-8").read():
    print("ALREADY APPLIED"); sys.exit(0)
if not os.path.exists("agent/confidence.py"):
    print("agent/confidence.py missing - install the confidence patch first. Nothing changed."); sys.exit(1)
data = {}
for path, pairs in EDITS.items():
    s = open(path, encoding="utf-8").read()
    for i, (a, b) in enumerate(pairs, 1):
        if s.count(a) != 1:
            print(f"{path}: anchor {i} not found exactly once (found {s.count(a)}). Nothing changed."); sys.exit(1)
        s = s.replace(a, b)
    data[path] = s
stamp = time.strftime("%Y%m%d-%H%M%S")
for path, s in data.items():
    shutil.copy2(path, path + ".bak-" + stamp)
    open(path, "w", encoding="utf-8").write(s)
open(NEWFILE[0], "w", encoding="utf-8").write(NEWFILE[1])
print("APPLIED. backups: *.bak-" + stamp)
